antiPatterns.example:
// Avoid: Showing reasoning for trivial responses
<Reasoning steps={[
  { id: '1', content: 'I will say hello' }
]} />
<Message message={{ role: 'assistant', content: 'Hello!' }} />

// Prefer: Only show reasoning for complex tasks
<Reasoning steps={complexReasoning} />
<Message message={{ role: 'assistant', content: complexResponse }} />

// Avoid: Overly detailed steps
{ id: '1', content: 'I am now processing the request by analyzing each word and considering multiple interpretations...' }

// Prefer: Concise, clear steps
{ id: '1', content: 'Analyzing the request for key terms and intent.' }

// Avoid: Rendering with no steps
<Reasoning steps={[]} />

// Prefer: Conditionally render
{reasoningSteps.length > 0 && <Reasoning steps={reasoningSteps} />
